B=http://localhost:8083/api/versan; J='-H Content-Type:application/json'; CK=/tmp/ck.txt; rm -f $CK
t(){ printf '\n### %s\n' "$1"; }
p(){ curl -s -o /tmp/o -w '%{http_code} %{content_type}' $J "${@}"; echo; head -c 400 /tmp/o | sed 's/JVBER.*/<pdf>/'; echo; }
t "status sem sessão (401)";            p -b $CK -c $CK $B/cliente -d '{"acao":"status"}'
t "login senha errada (401)";           p -b $CK -c $CK $B/cliente -d '{"acao":"entrar","numeroDocumento":"52998224725","senha":"0000"}'
t "login ok (CPF sem máscara)";         p -b $CK -c $CK $B/cliente -d '{"acao":"entrar","numeroDocumento":"52998224725","senha":"4725"}'
t "cookie";                             grep ane_av $CK | awk '{print $1,$2,$3,$4,$5,$6, length($7)" bytes"}'
t "status com sessão";                  p -b $CK -c $CK $B/cliente -d '{"acao":"status"}'
t "debitos";                            p -b $CK -c $CK $B/cliente -d '{"acao":"debitos"}'
t "pagas 2026";                         p -b $CK -c $CK $B/cliente -d '{"acao":"pagas","ano":2026}'
t "consumo 2026";                       p -b $CK -c $CK $B/cliente -d '{"acao":"consumo","ano":2026}'
t "pix fatura própria";                 p -b $CK -c $CK $B/cliente -d '{"acao":"pix","idFatura":9001}'
t "barra fatura própria";               p -b $CK -c $CK $B/cliente -d '{"acao":"barra","idFatura":9002}'
t "pix de fatura de OUTRO imóvel (404)";p -b $CK -c $CK $B/cliente -d '{"acao":"pix","idFatura":9101}'
t "pdf fatura paga 2025";               p -b $CK -c $CK $B/cliente -d '{"acao":"pdf","idFatura":7001}'
t "pdf fatura inexistente (404)";       p -b $CK -c $CK $B/cliente -d '{"acao":"pdf","idFatura":123456}'
t "selecionar CDC alheio (403)";        p -b $CK -c $CK $B/cliente -d '{"acao":"selecionar","cdc":"777"}'
t "selecionar 1002";                    p -b $CK -c $CK $B/cliente -d '{"acao":"selecionar","cdc":"1002"}'
t "debitos 1002";                       p -b $CK -c $CK $B/cliente -d '{"acao":"debitos"}'
t "cookie adulterado (401)";            curl -s -o /dev/null -w '%{http_code}\n' $J -H 'Cookie: ane_av_sessao=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA' $B/cliente -d '{"acao":"status"}'
t "origem estranha (403)";              p -H 'Origin: https://evil.example' -b $CK $B/cliente -d '{"acao":"status"}'
t "GET (405)";                          curl -s -o /dev/null -w '%{http_code}\n' $B/cliente
t "conferencia com sessão";             p -b $CK $B/conferencia-fatura -d '{"cdc":"1001","idFatura":9001}'
t "conferencia sem sessão (501)";       p $B/conferencia-fatura -d '{"cdc":"1001","idFatura":9001}'
t "sair";                               p -b $CK -c $CK $B/cliente -d '{"acao":"sair"}'
t "status após sair (401)";             p -b $CK -c $CK $B/cliente -d '{"acao":"status"}'
echo; echo "=========== PÚBLICO"
t "consultar 1001";                     p $B/segunda-via-publica -d '{"acao":"consultar","cdc":"1001"}'
t "consultar CDC sem débitos";          p $B/segunda-via-publica -d '{"acao":"consultar","cdc":"5555"}'
t "consultar CDC inválido (400)";       p $B/segunda-via-publica -d '{"acao":"consultar","cdc":"abc"}'
t "codigoBarras ok";                    p $B/segunda-via-publica -d '{"acao":"codigoBarras","cdc":"1001","idFatura":9001}'
t "segundaVia PDF ofuscado";            p $B/segunda-via-publica -d '{"acao":"segundaVia","cdc":"1001","idFatura":9002}'
t "segundaVia fatura de outro CDC (404)"; p $B/segunda-via-publica -d '{"acao":"segundaVia","cdc":"1001","idFatura":9101}'
t "pix-rapido ok";                      p $B/pix-rapido -d '{"acao":"pix","cdc":"1002","idFatura":9101}'
t "pix-rapido fatura alheia (404)";     p $B/pix-rapido -d '{"acao":"pix","cdc":"1002","idFatura":9001}'
t "email sem X-Requested-With (400)";   p $B/enviar-fatura-email -d '{"cdc":"1001","idFatura":9001,"email":"a@b.com"}'
t "email inválido (400)";               p -H 'X-Requested-With: XMLHttpRequest' $B/enviar-fatura-email -d '{"cdc":"1001","idFatura":9001,"email":"nao-e-email"}'
t "email ok";                           p -H 'X-Requested-With: XMLHttpRequest' $B/enviar-fatura-email -d '{"cdc":"1001","idFatura":9001,"email":"cliente@exemplo.com"}'
t "email: 4 envios mesmo destino → 429 no 4º"; for i in 1 2 3; do curl -s -o /dev/null -w '%{http_code} ' $J -H 'X-Requested-With: XMLHttpRequest' -H "X-Forwarded-For: 10.0.0.$i" $B/enviar-fatura-email -d '{"cdc":"1001","idFatura":9002,"email":"x@exemplo.com"}'; done; echo
